      "mainEntity": [
        {
          "@type": "Question",
          "name": "What if the power fault is not present during the visit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Give the electrician the timing and affected areas so the assessment can be scoped. An intermittent symptom may not be resolved in a single visit. Ask what investigation is included and what further testing or access would require approval."
          }
        },
        {
          "@type": "Question",
          "name": "Does fault finding include replacing the faulty equipment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Investigation identifies the proposed next step; repair or replacement may be a separate task. The quote should state the included assessment and any additional work before you approve it."
          }
        },
        {
          "@type": "Question",
          "name": "Why does only one part of a house lose power?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A fault can affect one circuit or connection while other rooms still have power. Working lights do not establish outlet safety. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Can you investigate an intermittent power fault?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. An intermittent fault can be investigated, although its timing may require more than one assessment stage. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to diagnose the problem first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Describe the observable change and property context. We inspect the affected area on site to establish the cause and confirm the repair scope. If more access is needed, we agree it with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "What information helps with a power-fault enquiry?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "List the affected rooms or circuits, what happened first, what was in use and any warning signs you can observe safely."
          }
        },
        {
          "@type": "Question",
          "name": "Should I keep resetting a tripping circuit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Avoid repeatedly resetting an electrical device that trips again."
          }
        },
        {
          "@type": "Question",
          "name": "What if I smell burning or see smoke?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Move to safety and call 000 if there is immediate danger."
          }
        },
        {
          "@type": "Question",
          "name": "Is fault finding included in the same scope as the repair?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Investigation and repair can involve separate tasks. We explain the assessment scope and the proposed corrective work, including components or circuit changes, before the written quote is agreed."
          }
        }
      ]
    }
